transfer.sketch:
gate(c) → keep | unknown
  if c.kind == indemnity and uncappedCue(c) == false: return unknown   -- cue frozen after the 800 labels

-- per class, one-versus-rest: controls from the same 800
batch = shuffle(realClauses ++ sample(controlsYes[c], 15) ++ sample(controlsNo[c], 15))

score(verdicts, controls) → { auc, brier, hi[c], lo[c], usableShare[c] }
  hi[c] = lowest p where precision(label = c | p ≥ hi) on controls ≥ 0.90
  lo[c] = highest p where precision(label ≠ c | p ≤ lo) on controls ≥ 0.90

for v in verdicts of real clauses:
  top = argmax(v.p)
  if v.p[top] ≥ hi[top] and forall other c: v.p[c] ≤ lo[c]: accept(v.clauseId, top)
  elif v.p[top] ≤ lo[top]:                               accept(v.clauseId, "no risk")   -- only if that band is calibrated
  else: queue.enqueue(v.clauseId, rank: v.p[top] − hi[top], showVerdict: false)
for v in auditSample(accepted): queue.enqueue(v.clauseId, showVerdict: false)
-- queue capped at 3,000: review highest rank first, remainder stays unknown, never accepted
for c in controls where agreeCount(judges, against: c.truth, p > 0.8) ≥ 2: queue.enqueue(c.id, showVerdict: false)
if auditPrecision(accepted) < target: withdraw(hi, lo) -- send the band back to review
